"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["40014"],{54129(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>c,frontMatter:()=>i,contentTitle:()=>r,toc:()=>h,assets:()=>l});var a=JSON.parse('{"id":"qiangguo/maopoemflaws3","title":"","description":"In Part Two, I already gave Mao Zedong\'s poetry a clear positioning. At the level of \\"seeing mountains as mountains, seeing water as water,\\" all discussions of style, spirit, and resonance are meaningful. However, this young lady does not intend to use such terminology for analysis. Instead, let me use the most ordinary word: \\"flavor.\\" So-called flavor has tangible forms and intangible forms; some can be savored through chewing, and some cannot be chewed but can only be apprehended spiritually -- the so-called flavor beyond the flavor. Tangible things are easy to discuss; intangible ones are more troublesome. In the past, people liked to use the metaphor of \\"salt in water\\" to approach the intangible -- but in this young lady\'s view, \\"salt in water\\" only speaks to the inseparability of a poem\'s form and its flavor. Yet this inseparability is still crude. According to modern science, they can actually be separated at the molecular level. So this metaphor, which may have been somewhat meaningful in ancient times, is completely pointless now.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/maopoemflaws3.md","sourceDirName":"qiangguo","slug":"/qiangguo/maopoemflaws3","permalink":"/en/qiangguo/maopoemflaws3","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"maopoemflaws3","title":"","hide_table_of_contents":true,"sidebar_label":"An objective evaluation of flaws in Mao Zedong\'s poetry (Part 3)"},"sidebar":"qiangguoSidebar","previous":{"title":"An objective evaluation of flaws in Mao Zedong\'s poetry (Part 2)","permalink":"/en/qiangguo/maopoemflaws2"},"next":{"title":"An objective evaluation of flaws in Mao Zedong\'s poetry (Part 4)","permalink":"/en/qiangguo/maopoemflaws4"}}'),o=n(74848),s=n(28453);let i={id:"maopoemflaws3",title:"",hide_table_of_contents:!0,sidebar_label:"An objective evaluation of flaws in Mao Zedong's poetry (Part 3)"},r="An Objective Evaluation of the Flaws in Mao Zedong's Poetry (Part Three)",l={},h=[];function d(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"an-objective-evaluation-of-the-flaws-in-mao-zedongs-poetry-part-three",children:"An Objective Evaluation of the Flaws in Mao Zedong's Poetry (Part Three)"})}),"\n",(0,o.jsx)(t.p,{children:'In Part Two, I already gave Mao Zedong\'s poetry a clear positioning. At the level of "seeing mountains as mountains, seeing water as water," all discussions of style, spirit, and resonance are meaningful. However, this young lady does not intend to use such terminology for analysis. Instead, let me use the most ordinary word: "flavor." So-called flavor has tangible forms and intangible forms; some can be savored through chewing, and some cannot be chewed but can only be apprehended spiritually -- the so-called flavor beyond the flavor. Tangible things are easy to discuss; intangible ones are more troublesome. In the past, people liked to use the metaphor of "salt in water" to approach the intangible -- but in this young lady\'s view, "salt in water" only speaks to the inseparability of a poem\'s form and its flavor. Yet this inseparability is still crude. According to modern science, they can actually be separated at the molecular level. So this metaphor, which may have been somewhat meaningful in ancient times, is completely pointless now.'}),"\n",(0,o.jsx)(t.p,{children:"Today, let us set aside Mao Zedong's poetry and first look at Li Shangyin's \"Tianya\" (The Ends of the Earth):"}),"\n",(0,o.jsxs)(t.blockquote,{children:["\n",(0,o.jsx)(t.p,{children:"\u6625\u65E5\u5728\u5929\u6DAF\uFF0C\u5929\u6DAF\u65E5\u53C8\u659C\u3002\u83BA\u557C\u5982\u6709\u6CEA\uFF0C\u4E3A\u6E7F\u6700\u9AD8\u82B1\u3002"}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:'A spring day at the ends of the earth, and at the ends of the earth the sun slants toward dusk. Flowers blooming at their highest branch signal their imminent exhaustion, and once they are spent, spring too is spent. The spring day nears dusk; spring itself nears dusk. The warbler\'s cry evokes both birdsong and weeping, bringing forth tears to moisten the highest flower. Is it spring? Is it a human life? An era? An infinite cycle of rebirth? "As if with tears" -- yet do tears truly exist? Without tears, with tears -- but the spring day is always at the ends of the earth, and the sun at the ends of the earth will always slant away. Frustrated ambition, desolate solitude, the fading of life, the exile at the world\'s edge, the shattering of ideals, the wounds of existence -- all become superfluous words. The vast cosmos is entirely lost in that tangible-intangible drop of tears. Regardless of who you are, you are always in this moment of "the warbler cries as if with tears, to moisten the highest flower." At this moment, this existence encompasses the six directions -- it is simply that ordinary people cannot experience it, cannot express it. And Li Shangyin\'s twenty characters cover heaven and earth. How could the mere piling up of grand imagery ever achieve this? The entire universe melts in this single tangible-intangible tear. Here, all commentary is superfluous.'}),"\n",(0,o.jsx)(t.p,{children:'In a certain sense, only when this realm is attained can something be called poetry. True poetry must be in communion with the entire universe -- the most delicate yet the most majestic, all oppositions dissolved within it without losing a single detail. Before this kind of true poetry, all talk of style, manner, spirit, and resonance becomes putting a hat on top of a hat. All talk of history, space-time, and such becomes a joke. All is one, one is all, and yet on what does this "one" stand? All dharmas return to one -- where does the one return? Go contemplate these twenty characters. As the saying goes: words of feeling, words of Chan, a single luminous pearl, neither form nor emptiness -- appearing as it is to whoever comes. This young lady speaks no false words.'}),"\n",(0,o.jsx)(t.p,{children:"I hope the above analysis will help broaden everyone's poetic horizons. To keep poetry stuck at the level of quasi-sexual discharge not only insults poetry but insults oneself. Poetry is Being, Being is poetry -- how could you possibly not dwell poetically?"})]})}function c(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var a=n(96540);let o={},s=a.createContext(o);function i(e){let t=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),a.createElement(s.Provider,{value:t},e.children)}}}]);